// ============================================================
// Optional outbound email for auth links.
//
// Enabled when SMTP_URL is set, e.g.
//   SMTP_URL=smtps://user:pass@smtp.example.com:465
//   MAIL_FROM="wacrm <no-reply@example.com>"
//
// Without SMTP the app still works: signups are confirmed immediately
// and password-reset links are generated by an owner (Settings →
// Members) or the CLI (`node scripts/auth-cli.mjs reset-link <email>`).
// ============================================================

import { getT } from "@/lib/i18n/translate";

const t = getT("Auth.email");

export function isMailEnabled(): boolean {
  return Boolean(process.env.SMTP_URL);
}

type Transport = { sendMail(opts: Record<string, unknown>): Promise<unknown> };
let transport: Promise<Transport> | null = null;

function getTransport(): Promise<Transport> {
  transport ??= import("nodemailer").then((m) => m.createTransport(process.env.SMTP_URL!) as Transport);
  return transport;
}

export type AuthEmailKind = "signupConfirm" | "recovery" | "emailChange";

export async function sendAuthEmail(kind: AuthEmailKind, to: string, link: string): Promise<void> {
  if (!isMailEnabled()) throw new Error("SMTP is not configured");
  const subject = t(`${kind}.subject`);
  const intro = t(`${kind}.body`);
  const ignore = t("ignore");
  const text = `${intro}\n\n${link}\n\n${ignore}\n`;
  const html =
    `<p>${escapeHtml(intro)}</p>` +
    `<p><a href="${escapeHtml(link)}">${escapeHtml(t(`${kind}.cta`))}</a></p>` +
    `<p style="color:#666;font-size:12px">${escapeHtml(ignore)}</p>`;
  const tr = await getTransport();
  await tr.sendMail({
    from: process.env.MAIL_FROM ?? "wacrm <no-reply@localhost>",
    to,
    subject,
    text,
    html,
  });
}

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}
